sys_variable_value.value:
(function execute(inputs, outputs) {
  outputs.endpoint   = '';
  outputs.q_location = '';
  outputs.q_units    = 'c';
  outputs.q_format   = 'json';
  outputs.h_key      = '';
  outputs.h_host     = 'yahoo-weather5.p.rapidapi.com';

  var baseId = '';
  if (inputs.base) {
    if (typeof inputs.base === 'string') {
      baseId = String(inputs.base);
    } else if (typeof inputs.base === 'object') {
      baseId = String(inputs.base.sys_id || inputs.base.value || '');
    }
  }
  if (!baseId) {
    throw new Error('Missing base sys_id');
  }

  var baseGR = new GlideRecord('x_1834930_office_0_office_base');
  if (!baseGR.get(baseId)) {
    throw new Error('Office Base not found');
  }

  var city  = baseGR.getValue('city')  || '';
  var state = baseGR.getValue('state') || '';
  var location = [city, state].filter(function(s){ return s && s.trim(); }).join(', ');
  if (!location) {
    throw new Error('Base must have City and State');
  }

  var active  = gs.getProperty('x_1834930_office_0.Weather API - active', 'true');
  if (String(active).toLowerCase() !== 'true') {
    throw new Error('Integration disabled by property');
  }

  var endpoint = gs.getProperty('x_1834930_office_0.Weather API - endpoint', '');
  if (!endpoint) {
    throw new Error('Missing endpoint property');
  }

  var apiKey   = gs.getProperty('x_1834930_office_0.Weather API - apikey', '');
  if (!apiKey) {
    throw new Error('Missing API key property');
  }

  outputs.endpoint   = endpoint;
  outputs.q_location = location;
  outputs.h_key      = apiKey;
})(inputs, outputs);

